"""Expert parameters are generated by global expert ID on their owning rank."""
from dataclasses import dataclass, replace

from common.routing import generate


@dataclass
class Workload:
    hidden_states: object
    topk_ids: object
    topk_weights: object
    w_gate: object
    w_up: object
    w_down: object
    grad_output: object
    router_weight: object
    local_experts: tuple[int, ...]
    route: object
    limit: float

    def leaves(self):
        return (self.hidden_states, self.topk_weights, self.w_gate, self.w_up, self.w_down)

    def with_hidden(self, value):
        return replace(self, hidden_states=value)


def random_tensor(torch, shape, seed, scale=1):
    generator = torch.Generator(device="cpu").manual_seed(seed % (2**63))
    return torch.randn(shape, generator=generator, dtype=torch.float32) * scale


def expert_parameters(torch, config, expert):
    model = config["model"]
    h, i = model["hidden_size"], model["intermediate_size"]
    seed = config["workload"]["seed"] + 1_000_003 + 11 * expert
    return (
        random_tensor(torch, (i, h), seed, h ** -0.5),
        random_tensor(torch, (i, h), seed + 1, h ** -0.5),
        random_tensor(torch, (h, i), seed + 2, i ** -0.5),
    )


def activation_inputs(torch, config, rank, step, tokens):
    h = config["model"]["hidden_size"]
    seed = config["workload"]["seed"] + 10007 * (rank + 1) + 999983 * step
    return (random_tensor(torch, (tokens, h), seed),
            random_tensor(torch, (tokens, h), seed + 1, h ** -0.5))


def make_workload(context, step=0, allocate_weights=True):
    torch, cfg, rank = context.torch, context.config, context.rank
    model = cfg["model"]
    dtype = getattr(torch, model["dtype"])
    route = generate(cfg, rank, step)
    owned = tuple(expert for expert, owner in enumerate(route.placement) if owner == rank)
    x, dy = activation_inputs(torch, cfg, rank, step, route.tokens[rank])
    x = x.to(context.device, dtype).requires_grad_()
    dy = dy.to(context.device, dtype)
    probabilities = torch.from_numpy(route.weights).to(context.device, dtype).requires_grad_()
    if allocate_weights:
        h, i = model["hidden_size"], model["intermediate_size"]
        parameters = [expert_parameters(torch, cfg, e) for e in owned]
        shapes = ((0, i, h), (0, i, h), (0, h, i))
        tensors = [
            (torch.stack([group[index] for group in parameters]) if parameters
             else torch.empty(shape)).to(context.device, dtype).requires_grad_()
            for index, shape in enumerate(shapes)
        ]
    else:
        tensors = [None, None, None]
    router_weight = random_tensor(torch, (model["num_experts"], model["hidden_size"]),
                                  cfg["workload"]["seed"] + 7499,
                                  model["hidden_size"] ** -0.5)
    router_weight = router_weight.to(context.device, dtype).requires_grad_()
    return Workload(x, torch.from_numpy(route.ids).to(context.device), probabilities,
                    *tensors, dy, router_weight, owned, route, model["swiglu_limit"])


def router(workload):
    logits = workload.hidden_states @ workload.router_weight.T
    values, ids = logits.topk(workload.topk_ids.shape[-1])
    return replace(workload, topk_ids=ids, topk_weights=values.float().softmax(-1).to(logits.dtype))
